      try{const loaded=await retrieveSourceText(source);resolved={...source,passages:loaded.passages,textStatus:loaded.textStatus,textOrigin:loaded.textOrigin,textMessage:loaded.textMessage,textRetrievedAt:loaded.textRetrievedAt};if(useWorkspace.getState().paper?.id===paper.id)useWorkspace.getState().updateSource(resolved);}catch{resolved={...source,textStatus:'unavailable',textMessage:'Article text could not be retrieved. Import its PDF to verify quotations.'};if(useWorkspace.getState().paper?.id===paper.id)useWorkspace.getState().updateSource(resolved);}
