  useEffect(()=>{mounted.current=true;return()=>{mounted.current=false;};},[]);
  useEffect(()=>{function close(event:PointerEvent){if(!popover.current?.contains(event.target as Node))onClose();}function key(event:KeyboardEvent){if(event.key==='Escape'){onClose();initial.editor.commands.focus();}}document.addEventListener('pointerdown',close);document.addEventListener('keydown',key);return()=>{document.removeEventListener('pointerdown',close);document.removeEventListener('keydown',key);};},[]);
  const anchor=initial.position||{left:window.innerWidth/2-170,top:140};const left=Math.max(12,Math.min(anchor.left,window.innerWidth-354)),top=Math.max(72,Math.min(anchor.top,window.innerHeight-400));
