  return <Modal title={initial.title?'Edit source':'Add a source'} onClose={onClose} wide><form onSubmit={event=>{event.preventDefault();if(source.title.trim())onSave({...source,title:source.title.trim()});}}><div className="form-grid"><label className="span-2">Title<input autoFocus value={source.title} onChange={e=>field('title',e.target.value)} required placeholder="Article, book, or web page title"/></label><label>Source type<select value={source.type} onChange={e=>field('type',e.target.value)}><option value="article-journal">Journal article</option><option value="paper-conference">Conference paper</option><option value="book">Book</option><option value="webpage">Web page</option></select></label><label>Publication year<input value={source.year} onChange={e=>field('year',e.target.value)} placeholder="2026"/></label><label className="span-2">Authors<textarea rows={2} value={source.authors} onChange={e=>field('authors',e.target.value)} placeholder={'Surname, Given name\nOne author per line; organization names are also welcome.'}/><small>Use “Surname, Given name” for each person, one per line.</small></label><label>{source.type==='article-journal'?'Journal':source.type==='paper-conference'?'Proceedings':'Website / collection'}<input value={source.container} onChange={e=>field('container',e.target.value)}/></label><label>Publisher<input value={source.publisher} onChange={e=>field('publisher',e.target.value)}/></label><div className="form-grid span-2 three-columns"><label>Volume<input value={source.volume} onChange={e=>field('volume',e.target.value)}/></label><label>Issue<input value={source.issue} onChange={e=>field('issue',e.target.value)}/></label><label>Page range<input value={source.pages} onChange={e=>field('pages',e.target.value)} placeholder="15–28"/></label></div><label>DOI<input value={source.doi} onChange={e=>field('doi',e.target.value)} placeholder="10.…"/></label><label>Accessed<input type="date" value={source.accessed} onChange={e=>field('accessed',e.target.value)}/></label><label className="span-2">Original URL<input type="url" value={source.url} onChange={e=>field('url',e.target.value)} placeholder="https://…"/></label></div><details className="form-disclosure"><summary>Bibliography wording <span>{styles[style]}</span></summary><p className="form-hint">Leave this empty for automatic formatting. Your custom wording applies to this style only; source details still drive in-text citations.</p><textarea aria-label="Custom bibliography entry" rows={4} value={source.overrides?.[style]||''} onChange={e=>setSource(s=>({...s,overrides:{...s.overrides,[style]:e.target.value}}))} placeholder="Optional custom reference entry…"/></details><details className="form-disclosure"><summary>Saved passages <span>{source.savedPassages.length}</span></summary><p className="form-hint">Save exact wording with its location. Pasted quotations and /cite can use these saved locations. Only wording found in article text is marked as verified.</p>{source.savedPassages.map(p=><div className="saved-passage" key={p.id}><p>“{p.text}”</p><span>{p.locatorType} {p.locator}</span><button type="button" className="icon-button" aria-label="Remove saved passage" onClick={()=>setSource(s=>({...s,savedPassages:s.savedPassages.filter(item=>item.id!==p.id)}))}><X size={14}/></button></div>)}<label>Passage<textarea rows={3} value={passage} onChange={e=>setPassage(e.target.value)} placeholder="Copy the exact passage you want to keep…"/></label><div className="form-grid locator-fields"><label>Location type<select value={locatorType} onChange={e=>setLocatorType(e.target.value as LocatorType)}><option value="page">Page</option><option value="paragraph">Paragraph</option><option value="section">Section</option></select></label><label>Location<input value={location} onChange={e=>setLocation(e.target.value)} placeholder="Printed page or exact section"/></label></div><button type="button" className="button subtle" disabled={!passage.trim()||!location.trim()} onClick={()=>{setSource(s=>({...s,savedPassages:[...s.savedPassages,{id:uid(),text:passage.trim(),locator:location.trim(),locatorType}]}));setPassage('');setLocation('');}}>Keep this passage</button></details><div className="modal-actions"><button type="button" className="button subtle" onClick={onClose}>Cancel</button><button className="button primary" disabled={!source.title.trim()}>Save source</button></div></form></Modal>;
